def transform(g):
    h,w=len(g),len(g[0])
    drows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=0]
    dcols=[j for j in range(w) if len(set(g[i][j] for i in range(h)))==1 and g[0][j]!=0]
    dv=set(g[i][0] for i in drows)|set(g[0][j] for j in dcols)
    colors=set(x for row in g for x in row if x)-dv
    def isblock(c):
        cs=set((i,j) for i in range(h) for j in range(w) if g[i][j]==c)
        while cs:
            i,j=min(cs)
            if not all((i+di,j+dj) in cs for di in range(2) for dj in range(2)): return False
            for di in range(2):
                for dj in range(2): cs.discard((i+di,j+dj))
        return True
    blockc={c for c in colors if isblock(c)}
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j] not in dv|blockc and g[i][j]!=0]
    starts_r=[0]+[i+1 for i in drows]; ends_r=drows+[h]
    starts_c=[0]+[j+1 for j in dcols]; ends_c=dcols+[w]
    rb=list(zip(starts_r,ends_r)); cb=list(zip(starts_c,ends_c))
    def band(i,bounds):
        for a,b in bounds:
            if a<=i<b: return a
    r0=band(cells[0][0],rb); c0=band(cells[0][1],cb)
    offs=[(i-r0,j-c0) for i,j in cells]
    out=[[g[i][j] if j in dcols or i in drows else 0 for j in range(w)] for i in range(h)]
    for (a,b) in rb:
        col=None
        for i in range(a,b-1):
            for j in range(w-1):
                c=g[i][j]
                if c in blockc and c==g[i][j+1]==g[i+1][j]==g[i+1][j+1]: col=c
        if col is None: continue
        for (di,dj) in offs:
            for (ca,cbb) in cb:
                out[a+di][ca+dj]=col
    return out
